'use strict';
/* Keep - frontend SPA */

(function () {
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => Array.from(document.querySelectorAll(sel));

  const COLORS = [
    { name: 'Default', cls: 'color-default', bg: '#ffffff' },
    { name: 'Red', cls: 'color-red', bg: '#f28b82' },
    { name: 'Orange', cls: 'color-orange', bg: '#fbbc04' },
    { name: 'Yellow', cls: 'color-yellow', bg: '#fff475' },
    { name: 'Green', cls: 'color-green', bg: '#ccff90' },
    { name: 'Teal', cls: 'color-teal', bg: '#a7ffeb' },
    { name: 'Blue', cls: 'color-blue', bg: '#cbf0f8' },
    { name: 'Purple', cls: 'color-purple', bg: '#d7aefb' },
    { name: 'Pink', cls: 'color-pink', bg: '#fdcfe8' },
    { name: 'Brown', cls: 'color-brown', bg: '#e6c9a8' },
    { name: 'Grey', cls: 'color-grey', bg: '#e8eaed' },
    { name: 'Light green', cls: 'color-light-green', bg: '#b7e4c7' },
  ];

  let notes = [];
  let labels = [];
  let settings = { moveToBottom: false };
  let view = 'grid';            // grid | list
  let side = 'notes';           // notes | reminders | label:<name> | archive | trash | edit-labels
  let query = '';
  let editId = null;            // note id in composer/overlay, or '__new__' for a fresh composer note
  let pendingPinned = false;
  let pendingLabels = null;
  let snackbarTimer = null;

  // ---------- API ----------
  async function api(path, method, body) {
    const opts = { method: method || 'GET', headers: {} };
    if (body !== undefined) {
      opts.headers['Content-Type'] = 'application/json';
      opts.body = JSON.stringify(body);
    }
    const res = await fetch(path, opts);
    if (!res.ok) throw new Error('Request failed: ' + res.status);
    return res.json();
  }

  // ---------- Snackbar ----------
  function showSnackbar(text, actionLabel, actionFn) {
    clearTimeout(snackbarTimer);
    const bar = $('#snackbar');
    $('#snackbar-text').textContent = text;
    const action = $('#snackbar-action');
    if (actionLabel && actionFn) {
      action.textContent = actionLabel;
      action.classList.remove('hidden');
      action.onclick = (e) => { e.stopPropagation(); actionFn(); };
    } else {
      action.classList.add('hidden');
      action.onclick = null;
    }
    $('#snackbar-close').onclick = () => hideSnackbar();
    bar.classList.remove('hidden');
    snackbarTimer = setTimeout(hideSnackbar, 5000);
  }

  function hideSnackbar() {
    clearTimeout(snackbarTimer);
    $('#snackbar').classList.add('hidden');
    $('#snackbar-action').classList.add('hidden');
  }

  // ---------- Escaping ----------
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // ---------- Composer ----------
  function composerOpen() {
    return $('#composer').classList.contains('open');
  }

  function renderComposer() {
    const el = $('#composer');
    const isOpen = composerOpen();
    const note = editId && editId !== '__new__' ? notes.find((n) => n.id === editId) : null;
    const pinLabel = (note && note.pinned) || pendingPinned ? 'Unpin' : 'Pin';

    let html = '';
    if (isOpen) {
      html += '<input id="note-title-input" type="text" class="composer-title" placeholder="Title" aria-label="Title" autocomplete="off" value="' + esc(note ? note.title || '' : '') + '">';
      html += '<textarea id="note-content-input" class="composer-content" placeholder="Take a note..." aria-label="Take a note" rows="1">' + esc(note ? note.content || '' : '') + '</textarea>';
      html += '<div class="composer-actions">';
      html += '<button type="button" class="icon-btn" data-action="palette" aria-label="Background options" title="Background options">🎨</button>';
      html += '<button type="button" class="icon-btn" data-action="more" aria-label="More options" title="More options">⋯</button>';
      html += '<button type="button" class="icon-btn" data-action="pin" aria-label="' + pinLabel + '" title="' + pinLabel + '">📌</button>';
      html += '<span class="composer-spacer"></span>';
      html += '<button type="button" class="text-btn" data-action="close">Close</button>';
      html += '</div>';
      html += '<div id="composer-palette" class="palette hidden"></div>';
      html += '<div id="composer-menu" class="ctx-menu hidden"></div>';
    } else {
      html += '<div class="composer-hint" id="composer-hint">Take a note...</div>';
    }
    el.innerHTML = html;
    if (isOpen) {
      if (note && note.color) el.style.background = note.color;
      else if (composerColor) el.style.background = composerColor;
      renderComposerPalette();
    } else {
      el.style.background = '';
    }
  }

  let composerColor = '';

  function renderComposerPalette() {
    const pal = $('#composer-palette');
    if (!pal) return;
    pal.innerHTML = COLORS.map((c) =>
      '<button type="button" class="color-swatch ' + c.cls + '" data-color="' + c.bg + '" aria-label="' + c.name + '" title="' + c.name + '"></button>'
    ).join('');
  }

  function openComposer() {
    if (composerOpen()) return;
    editId = '__new__';
    pendingPinned = false;
    pendingLabels = null;
    composerColor = '';
    $('#composer').classList.add('open');
    renderComposer();
    const ta = $('#note-content-input');
    if (ta) ta.focus();
  }

  function closeComposer(save) {
    if (!composerOpen()) { if (editId === '__new__') editId = null; return; }
    const title = $('#note-title-input') ? $('#note-title-input').value.trim() : '';
    const content = $('#note-content-input') ? $('#note-content-input').value : '';
    const note = editId && editId !== '__new__' ? notes.find((n) => n.id === editId) : null;
    if (save && (title || content.trim())) {
      const payload = {
        title: title || '',
        content: content || '',
        color: composerColor || (note ? note.color : '') || '',
      };
      if (note) {
        api('/api/notes/' + note.id, 'PATCH', payload).then(() => { reload(); }).catch(() => {});
      } else {
        payload.pinned = pendingPinned;
        if (pendingLabels) payload.labels = pendingLabels;
        api('/api/notes', 'POST', payload).then(() => { reload(); }).catch(() => {});
      }
    }
    editId = null;
    pendingPinned = false;
    pendingLabels = null;
    composerColor = '';
    $('#composer').classList.remove('open');
    $('#composer').style.background = '';
    renderComposer();
  }

  // ---------- Label dialog ----------
  function openLabelDialog(noteId) {
    editId = noteId;
    const note = noteId && noteId !== '__new__' ? notes.find((n) => n.id === noteId) : null;
    const current = note ? note.labels || [] : (pendingLabels || []);
    const list = $('#labels-dialog-list');
    list.innerHTML = labels.map((l) => {
      const checked = current.includes(l.name);
      return '<label class="label-check-row">' +
        '<input type="checkbox" value="' + esc(l.name) + '"' + (checked ? ' checked' : '') + '>' +
        '<span>' + esc(l.name) + '</span></label>';
    }).join('');
    $('#labels-dialog').classList.remove('hidden');
  }

  function closeLabelDialog() {
    $('#labels-dialog').classList.add('hidden');
    $('#labels-dialog-list').innerHTML = '';
  }

  // ---------- Note edit overlay ----------
  function openNoteEditor(noteId) {
    const note = notes.find((n) => n.id === noteId);
    if (!note) return;
    editId = noteId;
    const body = $('#edit-overlay-body');
    const pinLabel = note.pinned ? 'Unpin' : 'Pin';
    body.innerHTML =
      '<input id="edit-title-input" type="text" class="composer-title" placeholder="Title" aria-label="Title" value="' + esc(note.title || '') + '" autocomplete="off">' +
      '<textarea id="edit-content-input" class="composer-content" aria-label="Note content" rows="4">' + esc(note.content || '') + '</textarea>' +
      '<div class="composer-actions">' +
      '<button type="button" class="icon-btn" data-edit-action="palette" aria-label="Background options" title="Background options">🎨</button>' +
      '<button type="button" class="icon-btn" data-edit-action="more" aria-label="More options" title="More options">⋯</button>' +
      '<button type="button" class="icon-btn" data-edit-action="pin" aria-label="' + pinLabel + '" title="' + pinLabel + '">📌</button>' +
      '<span class="composer-spacer"></span>' +
      '<button type="button" id="edit-close" class="text-btn">Close</button>' +
      '</div>' +
      '<div id="edit-palette" class="palette hidden"></div>' +
      '<div id="edit-menu" class="ctx-menu hidden"></div>';
    $('#edit-overlay').classList.remove('hidden');
    renderEditPalette(note.color);
    const ta = $('#edit-content-input');
    if (ta) ta.focus();
  }

  function renderEditPalette(bg) {
    const pal = $('#edit-palette');
    if (!pal) return;
    pal.innerHTML = COLORS.map((c) =>
      '<button type="button" class="color-swatch ' + c.cls + '" data-color="' + c.bg + '" aria-label="' + c.name + '" title="' + c.name + '"></button>'
    ).join('');
  }

  function closeNoteEditor(save) {
    const overlay = $('#edit-overlay');
    if (overlay.classList.contains('hidden')) { editId = null; return; }
    const note = editId ? notes.find((n) => n.id === editId) : null;
    if (save && note) {
      const title = $('#edit-title-input') ? $('#edit-title-input').value.trim() : '';
      const content = $('#edit-content-input') ? $('#edit-content-input').value : '';
      const dialog = overlay.querySelector('.dialog');
      const bg = dialog.style.background || note.color || '';
      api('/api/notes/' + note.id, 'PATCH', { title: title || '', content: content || '', color: bg }).then(() => { reload(); }).catch(() => {});
    }
    editId = null;
    overlay.classList.add('hidden');
    const dialog = overlay.querySelector('.dialog');
    if (dialog) dialog.style.background = '';
    $('#edit-overlay-body').innerHTML = '';
  }

  // ---------- Floating action bar ----------
  function showFloatingBar(note) {
    const bar = $('#floating-bar');
    const pinLabel = note.pinned ? 'Unpin' : 'Pin';
    let buttons = '';
    if (side === 'trash') {
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="delete" aria-label="Delete" title="Delete">🗑</button>';
    } else if (side === 'archive') {
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="unarchive" aria-label="Unarchive" title="Unarchive">↩</button>';
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="more" aria-label="More options" title="More options">⋯</button>';
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="pin" aria-label="' + pinLabel + '" title="' + pinLabel + '">📌</button>';
    } else {
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="palette" aria-label="Background options" title="Background options">🎨</button>';
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="archive" aria-label="Archive" title="Archive">🗄</button>';
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="more" aria-label="More options" title="More options">⋯</button>';
      buttons += '<button type="button" class="icon-btn fab-action" data-fab="pin" aria-label="' + pinLabel + '" title="' + pinLabel + '">📌</button>';
    }
    bar.innerHTML = buttons + '<div id="fab-palette" class="fab-palette hidden"></div>';
    bar.dataset.noteId = note.id;
    bar.classList.remove('hidden');
  }

  function hideFloatingBar() {
    const bar = $('#floating-bar');
    bar.classList.add('hidden');
    bar.innerHTML = '';
  }

  function renderFabPalette() {
    const pal = $('#fab-palette');
    if (!pal) return;
    pal.innerHTML = COLORS.map((c) =>
      '<button type="button" class="color-swatch ' + c.cls + '" data-color="' + c.bg + '" aria-label="' + c.name + '" title="' + c.name + '"></button>'
    ).join('');
  }

  // ---------- Context menu ----------
  function showCtxMenu(items, anchorRect) {
    const menu = $('#ctx-menu');
    menu.innerHTML = items.map((it) =>
      '<button type="button" class="ctx-item" data-ctx-action="' + esc(it.action) + '">' + esc(it.label) + '</button>'
    ).join('');
    menu.classList.remove('hidden');
    const mw = menu.offsetWidth || 190;
    const mh = menu.offsetHeight || 40;
    let x = anchorRect ? anchorRect.right - mw : 120;
    let y = anchorRect ? anchorRect.bottom + 4 : 120;
    x = Math.max(4, Math.min(x, window.innerWidth - mw - 4));
    y = Math.max(4, Math.min(y, window.innerHeight - mh - 4));
    menu.style.left = x + 'px';
    menu.style.top = y + 'px';
  }

  function hideCtxMenu() {
    $('#ctx-menu').classList.add('hidden');
    $('#ctx-menu').innerHTML = '';
  }

  // ---------- Card rendering ----------
  function highlight(text) {
    if (!query) return esc(text);
    const lower = text.toLowerCase();
    const q = query.toLowerCase();
    let out = '';
    let i = 0;
    while (i < text.length) {
      const idx = lower.indexOf(q, i);
      if (idx === -1) { out += esc(text.slice(i)); break; }
      out += esc(text.slice(i, idx)) + '<mark>' + esc(text.slice(idx, idx + q.length)) + '</mark>';
      i = idx + q.length;
    }
    return out;
  }

  function cardHtml(n) {
    const title = n.title ? '<div class="note-title">' + highlight(n.title) + '</div>' : '';
    const content = n.content ? '<div class="note-content">' + highlight(n.content) + '</div>' : '';
    const lbls = (n.labels || []).map((l) => '<span class="note-label">' + esc(l) + '</span>').join('');
    const lblHtml = lbls ? '<div class="note-labels">' + lbls + '</div>' : '';
    return '<div class="note-card" data-id="' + esc(n.id) + '" style="background:' + esc(n.color || '#ffffff') + '">' +
      title + content + lblHtml + '</div>';
  }

  function renderSingle(secSel, items) {
    const sec = $(secSel);
    sec.innerHTML = items.map(cardHtml).join('');
    sec.classList.toggle('list', view === 'list');
  }

  // ---------- Main render ----------
  function render() {
    $$('#sidebar .side-item').forEach((el) => {
      el.classList.toggle('active', el.dataset.side === side);
    });
    $('#view-title').textContent = '';
    $('#trash-toolbar').classList.add('hidden');
    $('#pinned-heading').classList.add('hidden');
    $('#others-heading').classList.add('hidden');
    $('#pinned-section').innerHTML = '';
    $('#others-section').innerHTML = '';
    $('#notes-section').innerHTML = '';
    $('#notes-section').classList.remove('list');
    $('#notes-section').classList.remove('edit-labels-wrap');

    let list = notes.filter((n) => !n.deleted);

    if (side === 'archive') {
      list = list.filter((n) => n.archived);
      $('#view-title').textContent = 'Archive';
      renderSingle('#notes-section', list);
    } else if (side === 'trash') {
      list = notes.filter((n) => n.deleted);
      $('#view-title').textContent = 'Trash';
      $('#trash-toolbar').classList.remove('hidden');
      renderSingle('#notes-section', list);
    } else if (side === 'edit-labels') {
      renderEditLabels();
      return;
    } else {
      list = list.filter((n) => !n.archived);
      if (side === 'reminders') {
        list = list.filter((n) => (n.labels || []).includes('Reminders'));
        $('#view-title').textContent = 'Reminders';
        renderSingle('#notes-section', list);
      } else if (side && side.startsWith('label:')) {
        const name = side.slice(6);
        list = list.filter((n) => (n.labels || []).includes(name));
        $('#view-title').textContent = name;
        renderSingle('#notes-section', list);
      } else {
        if (query) {
          const q = query.toLowerCase();
          list = list.filter((n) =>
            (n.title || '').toLowerCase().includes(q) || (n.content || '').toLowerCase().includes(q)
          );
          renderSingle('#notes-section', list);
        } else {
          const pinned = list.filter((n) => n.pinned);
          const others = list.filter((n) => !n.pinned);
          $('#pinned-heading').classList.toggle('hidden', pinned.length === 0);
          $('#others-heading').classList.toggle('hidden', others.length === 0);
          $('#pinned-section').innerHTML = pinned.map(cardHtml).join('');
          $('#others-section').innerHTML = others.map(cardHtml).join('');
          $('#pinned-section').classList.toggle('list', view === 'list');
          $('#others-section').classList.toggle('list', view === 'list');
        }
      }
    }

    // Hide floating bar if its note is no longer in the current list
    const bar = $('#floating-bar');
    if (!bar.classList.contains('hidden')) {
      const id = bar.dataset.noteId;
      if (!list.some((n) => n.id === id)) hideFloatingBar();
    }
  }

  // ---------- Edit labels view ----------
  function renderEditLabels() {
    const sec = $('#notes-section');
    sec.innerHTML = '<div class="edit-labels-wrap">' +
      '<h3 class="view-title">Edit labels</h3>' +
      labels.map(editLabelRowHtml).join('') +
      '</div>';
  }

  function editLabelRowHtml(l) {
    return '<div class="edit-label-row" data-label-id="' + esc(l.id) + '">' +
      '<span class="label-ico">🏷</span>' +
      '<input type="text" value="' + esc(l.name) + '" aria-label="' + esc(l.name) + '" placeholder="Label name">' +
      '<button type="button" class="del-label-btn" aria-label="Delete label">✕</button>' +
      '</div>';
  }

  // ---------- Reload ----------
  function reload() {
    api('/api/notes').then((data) => {
      notes = data.notes || [];
      labels = data.labels || [];
      settings = data.settings || settings;
      renderLabelItems();
      render();
    }).catch(() => {});
  }

  // ---------- Sidebar label items ----------
  function renderLabelItems() {
    const wrap = $('#label-items');
    const custom = labels.filter((l) => l.name !== 'Reminders');
    wrap.innerHTML = custom.map((l) =>
      '<div class="side-item side-link" data-side="label:' + esc(l.name) + '"><span class="side-ico">🏷</span><span class="side-label">' + esc(l.name) + '</span></div>'
    ).join('');
  }

  // ---------- Events ----------
  function bindEvents() {
    // Composer
    $('#composer').addEventListener('click', (e) => {
      const el = $('#composer');
      if (!composerOpen()) {
        openComposer();
        return;
      }
      const btn = e.target.closest('[data-action]');
      if (!btn) return;
      const action = btn.dataset.action;
      if (action === 'close') {
        closeComposer(true);
      } else if (action === 'palette') {
        $('#composer-palette').classList.toggle('hidden');
      } else if (action === 'pin') {
        const note = editId && editId !== '__new__' ? notes.find((n) => n.id === editId) : null;
        if (note) {
          api('/api/notes/' + note.id, 'PATCH', { pinned: !note.pinned }).then(() => { reload(); }).catch(() => {});
        } else {
          pendingPinned = !pendingPinned;
          renderComposer();
        }
      } else if (action === 'more') {
        const menu = $('#composer-menu');
        menu.classList.toggle('hidden');
        if (!menu.classList.contains('hidden')) {
          menu.innerHTML = '<button type="button" class="ctx-item" data-ctx-action="labels">Change labels</button>';
        }
      }
    });
    $('#composer').addEventListener('input', (e) => {
      if (e.target.id === 'note-content-input') {
        e.target.style.height = 'auto';
        e.target.style.height = e.target.scrollHeight + 'px';
      }
    });
    $('#composer').addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        closeComposer(true);
      }
    });
    $('#composer').addEventListener('click', (e) => {
      const swatch = e.target.closest('.color-swatch');
      if (swatch) {
        composerColor = swatch.dataset.color;
        $('#composer').style.background = composerColor;
        $('#composer-palette').classList.add('hidden');
      }
      const item = e.target.closest('[data-ctx-action]');
      if (item && item.dataset.ctxAction === 'labels') {
        $('#composer-menu').classList.add('hidden');
        openLabelDialog(editId !== null ? editId : '__new__');
      }
    });

    // Sidebar
    $('#sidebar').addEventListener('click', (e) => {
      const item = e.target.closest('.side-item');
      if (!item) return;
      const s = item.dataset.side;
      if (s === 'edit-labels') { side = 'edit-labels'; query = ''; $('#search-input').value = ''; hideFloatingBar(); render(); return; }
      if (s) {
        side = s;
        query = '';
        $('#search-input').value = '';
        hideFloatingBar();
        render();
      }
    });

    // Floating bar
    $('#floating-bar').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-fab]');
      const swatch = e.target.closest('.color-swatch');
      if (swatch) {
        const id = $('#floating-bar').dataset.noteId;
        api('/api/notes/' + id, 'PATCH', { color: swatch.dataset.color }).then(() => { reload(); }).catch(() => {});
        $('#fab-palette').classList.add('hidden');
        return;
      }
      if (!btn) return;
      const id = $('#floating-bar').dataset.noteId;
      const note = notes.find((n) => n.id === id);
      if (!note) return;
      const action = btn.dataset.fab;
      if (action === 'archive') {
        api('/api/notes/' + id, 'PATCH', { archived: true }).then(() => {
          hideFloatingBar();
          reload();
          showSnackbar('Note archived', 'Undo', () => {
            api('/api/notes/' + id, 'PATCH', { archived: false }).then(() => { hideSnackbar(); reload(); }).catch(() => {});
          });
        }).catch(() => {});
      } else if (action === 'unarchive') {
        api('/api/notes/' + id, 'PATCH', { archived: false }).then(() => { hideFloatingBar(); reload(); }).catch(() => {});
      } else if (action === 'delete') {
        api('/api/notes/' + id, 'DELETE').then(() => {
          hideFloatingBar();
          reload();
          showSnackbar('Note deleted', 'Undo', () => {
            api('/api/notes/' + id + '/restore', 'POST').then(() => { hideSnackbar(); reload(); showSnackbar('Action undone'); }).catch(() => {});
          });
        }).catch(() => {});
      } else if (action === 'pin') {
        api('/api/notes/' + id, 'PATCH', { pinned: !note.pinned }).then(() => { reload(); }).catch(() => {});
      } else if (action === 'palette') {
        renderFabPalette();
        $('#fab-palette').classList.toggle('hidden');
      } else if (action === 'more') {
        showCtxMenu([
          { label: 'Delete Note', action: 'delete-note' },
          { label: 'Change labels', action: 'labels' },
        ], btn.getBoundingClientRect());
      }
    });

    // Context menu
    $('#ctx-menu').addEventListener('click', (e) => {
      const item = e.target.closest('[data-ctx-action]');
      if (!item) return;
      const action = item.dataset.ctxAction;
      const id = $('#floating-bar').dataset.noteId;
      hideCtxMenu();
      if (action === 'delete-note' && id) {
        api('/api/notes/' + id, 'DELETE').then(() => {
          hideFloatingBar();
          reload();
          showSnackbar('Note deleted', 'Undo', () => {
            api('/api/notes/' + id + '/restore', 'POST').then(() => { hideSnackbar(); reload(); showSnackbar('Action undone'); }).catch(() => {});
          });
        }).catch(() => {});
      } else if (action === 'labels' && id) {
        openLabelDialog(id);
      }
    });

    // Label dialog
    $('#labels-dialog-close').addEventListener('click', () => {
      const checked = $$('#labels-dialog-list input[type="checkbox"]:checked').map((c) => c.value);
      if (editId && editId !== '__new__') {
        api('/api/notes/' + editId, 'PATCH', { labels: checked }).then(() => { reload(); }).catch(() => {});
      } else if (editId === '__new__') {
        pendingLabels = checked;
        closeLabelDialog();
        if (composerOpen()) closeComposer(true);
        return;
      }
      closeLabelDialog();
    });

    // Edit overlay
    $('#edit-overlay').addEventListener('click', (e) => {
      const btn = e.target.closest('[data-edit-action]');
      if (btn) {
        const action = btn.dataset.editAction;
        const note = editId ? notes.find((n) => n.id === editId) : null;
        if (action === 'palette') $('#edit-palette').classList.toggle('hidden');
        else if (action === 'pin' && note) {
          api('/api/notes/' + note.id, 'PATCH', { pinned: !note.pinned }).then(() => { reload(); }).catch(() => {});
        } else if (action === 'more') {
          const menu = $('#edit-menu');
          menu.innerHTML = '<button type="button" class="ctx-item" data-edit-ctx="labels">Change labels</button>';
          menu.classList.toggle('hidden');
        }
        return;
      }
      const item = e.target.closest('[data-edit-ctx]');
      if (item) {
        $('#edit-menu').classList.add('hidden');
        if (editId) openLabelDialog(editId);
        return;
      }
      const swatch = e.target.closest('.color-swatch');
      if (swatch) {
        $('#edit-overlay').querySelector('.dialog').style.background = swatch.dataset.color;
        $('#edit-palette').classList.add('hidden');
      }
    });
    $('#edit-overlay').addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        e.stopPropagation();
        closeNoteEditor(true);
      }
    });
    $('#edit-overlay').addEventListener('click', (e) => {
      if (e.target.closest('#edit-close')) closeNoteEditor(true);
    });

    // Notes area
    $('#notes-area').addEventListener('mouseover', (e) => {
      const card = e.target.closest('.note-card');
      if (!card || card.dataset.hovered) return;
      card.dataset.hovered = '1';
      const note = notes.find((n) => n.id === card.dataset.id);
      if (note) showFloatingBar(note);
    });
    $('#notes-area').addEventListener('click', (e) => {
      const card = e.target.closest('.note-card');
      if (!card) return;
      if (side === 'trash' || side === 'archive') return;
      openNoteEditor(card.dataset.id);
    });

    // View toggle
    $('#view-toggle').addEventListener('click', () => {
      view = view === 'grid' ? 'list' : 'grid';
      const label = view === 'grid' ? 'List view' : 'Grid view';
      $('#view-toggle').setAttribute('aria-label', label);
      $('#view-toggle-label').textContent = label;
      render();
    });

    // Search
    $('#search-input').addEventListener('input', (e) => {
      query = e.target.value.trim();
      $('#search-clear').classList.toggle('hidden', !query);
      $('#search-suggestions').classList.add('hidden');
      side = 'notes';
      render();
    });
    $('#search-input').addEventListener('focus', () => {
      if (!query) {
        const box = $('#search-suggestions');
        box.innerHTML = '<button type="button" class="suggestion" data-filter="Reminders">Reminders</button>';
        box.classList.remove('hidden');
      }
    });
    $('#search-input').addEventListener('blur', () => {
      setTimeout(() => $('#search-suggestions').classList.add('hidden'), 150);
    });
    $('#search-suggestions').addEventListener('click', (e) => {
      const s = e.target.closest('.suggestion');
      if (!s) return;
      side = 'label:' + s.dataset.filter;
      query = '';
      $('#search-input').value = '';
      $('#search-suggestions').classList.add('hidden');
      render();
    });
    $('#search-clear').addEventListener('click', () => {
      query = '';
      $('#search-input').value = '';
      $('#search-clear').classList.add('hidden');
      side = 'notes';
      render();
    });

    // Settings
    $('#settings-btn').addEventListener('click', () => {
      $('#settings-menu').classList.toggle('hidden');
    });
    $('#settings-item').addEventListener('click', () => {
      $('#settings-menu').classList.add('hidden');
      $('#setting-bottom').checked = settings.moveToBottom;
      $('#settings-view').classList.remove('hidden');
    });
    $('#settings-save').addEventListener('click', () => {
      settings.moveToBottom = $('#setting-bottom').checked;
      api('/api/settings', 'POST', settings).then(() => { reload(); }).catch(() => {});
      $('#settings-view').classList.add('hidden');
    });
    $('#settings-cancel').addEventListener('click', () => {
      $('#settings-view').classList.add('hidden');
    });

    // Menu / sidebar collapse
    $('#menu-btn').addEventListener('click', () => {
      $('#sidebar').classList.toggle('collapsed');
    });

    // Empty trash
    $('#empty-trash-btn').addEventListener('click', () => {
      api('/api/trash', 'DELETE').then(() => {
        reload();
        showSnackbar('Trash emptied');
      }).catch(() => {});
    });

    // Edit labels view
    $('#notes-section').addEventListener('click', (e) => {
      if (side !== 'edit-labels') return;
      const row = e.target.closest('.edit-label-row');
      if (!row) return;
      if (e.target.closest('.del-label-btn')) {
        const id = row.dataset.labelId;
