'use strict';
/* Keep - zero-dependency Node backend */
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const PORT = parseInt(process.env.PORT, 10) || 43100;
const DATA_DIR = path.join(__dirname, 'data');
const DATA_FILE = path.join(DATA_DIR, 'db.json');
const DIST_DIR = path.resolve(__dirname, '..', 'frontend', 'dist');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

// ---------- Seed data ----------
function seed() {
  const now = Date.now();
  const note = (title, content, extra) =>
    Object.assign({ id: crypto.randomUUID(), title, content: content || '', color: '', pinned: false, archived: false, deleted: false, labels: [], createdAt: now, updatedAt: now }, extra);
  return {
    notes: [
      note('Sprint goals', 'Sprint goals for the current week', { pinned: true }),
      note('Groceries', 'Milk, eggs, bread'),
      note('Delete me 2.3.1', 'Temporary note for deletion flow'),
      note('Delete me 2.3.2', 'Temporary note for deletion flow'),
      note('Delete me 2.3.3', 'Temporary note for deletion flow'),
      note('Project ideas', 'Initial editable content'),
      note('Travel plans 2.5.1', 'Archive workflow note'),
      note('Travel plans 2.5.2', 'Archive workflow note'),
      note('Travel plans 2.5.3', 'Archive workflow note'),
      note('Travel plans 2.5.4', 'Archive workflow note'),
      note('Garden tasks existing', 'Color me later'),
      note('Team retro add label', 'Agenda for team retro'),
      note('Team retro remove label', 'Agenda for team retro', { labels: ['Work'] }),
      note('Design review', 'Review the new design proposal', { labels: ['Work'] }),
      note('Movie list', 'Inception, Arrival'),
      note('Call dentist existing', 'Remind me to call the dentist', { labels: ['Reminders'] }),
      note('Meeting agenda 2.8.1', 'Pin this note'),
      note('Meeting agenda 2.8.2', 'Pin this note'),
      note('Study schedule', 'Best study habits for exams'),
    ],
    labels: [
      { id: crypto.randomUUID(), name: 'Work' },
      { id: crypto.randomUUID(), name: 'Work editable' },
      { id: crypto.randomUUID(), name: 'Reminders' },
    ],
    settings: { moveToBottom: false },
  };
}

// ---------- Store ----------
let db = null;

function load() {
  try {
    if (fs.existsSync(DATA_FILE)) {
      db = JSON.parse(fs.readFileSync(DATA_FILE, 'utf8'));
      if (db && Array.isArray(db.notes) && Array.isArray(db.labels)) return;
    }
  } catch (e) {
    // fall through to reseed
  }
  db = seed();
  save();
}

function save() {
  fs.mkdirSync(DATA_DIR, { recursive: true });
  fs.writeFileSync(DATA_FILE, JSON.stringify(db, null, 2));
}

// ---------- HTTP helpers ----------
function sendJson(res, status, obj) {
  const body = JSON.stringify(obj);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) });
  res.end(body);
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (c) => { data += c; if (data.length > 1e6) req.destroy(); });
    req.on('end', () => {
      try { resolve(data ? JSON.parse(data) : {}); } catch (e) { reject(e); }
    });
    req.on('error', reject);
  });
}

function serveStatic(res, pathname) {
  let rel = decodeURIComponent(pathname);
  if (rel === '/' || rel === '') rel = '/index.html';
  const filePath = path.normalize(path.join(DIST_DIR, rel));
  if (!filePath.startsWith(DIST_DIR)) {
    res.writeHead(403); res.end('Forbidden');
    return;
  }
  fs.readFile(filePath, (err, data) => {
    if (err) {
      // SPA fallback to index.html for unknown paths
      fs.readFile(path.join(DIST_DIR, 'index.html'), (err2, idx) => {
        if (err2) { res.writeHead(404); res.end('Not found'); return; }
        res.writeHead(200, { 'Content-Type': MIME['.html'] });
        res.end(idx);
      });
      return;
    }
    const ext = path.extname(filePath).toLowerCase();
    res.writeHead(200, { 'Content-Type': MIME[ext] || 'application/octet-stream' });
    res.end(data);
  });
}

// ---------- API ----------
async function handleApi(req, res, pathname, query) {
  const method = req.method;
  const parts = pathname.split('/').filter(Boolean); // e.g. ['api','notes','<id>']

  // GET /api/notes
  if (method === 'GET' && parts.length === 2 && parts[1] === 'notes') {
    return sendJson(res, 200, { notes: db.notes, labels: db.labels, settings: db.settings });
  }

  // POST /api/notes
  if (method === 'POST' && parts.length === 2 && parts[1] === 'notes') {
    let body;
    try { body = await readBody(req); } catch (e) { return sendJson(res, 400, { error: 'invalid body' }); }
    const now = Date.now();
    const n = {
      id: crypto.randomUUID(),
      title: typeof body.title === 'string' ? body.title : '',
      content: typeof body.content === 'string' ? body.content : '',
      color: typeof body.color === 'string' ? body.color : '',
      pinned: !!body.pinned,
      archived: false,
      deleted: false,
      labels: Array.isArray(body.labels) ? body.labels.filter((l) => typeof l === 'string') : [],
      createdAt: now,
      updatedAt: now,
    };
    db.notes.push(n);
    save();
    return sendJson(res, 200, { note: n });
  }

  // PATCH /api/notes/:id
  if (method === 'PATCH' && parts.length === 3 && parts[1] === 'notes') {
    const n = db.notes.find((x) => x.id === parts[2]);
    if (!n) return sendJson(res, 404, { error: 'not found' });
    let body;
    try { body = await readBody(req); } catch (e) { return sendJson(res, 400, { error: 'invalid body' }); }
    const fields = ['title', 'content', 'color', 'pinned', 'archived', 'deleted'];
    for (const f of fields) if (body[f] !== undefined) n[f] = body[f];
    if (body.labels !== undefined && Array.isArray(body.labels)) n.labels = body.labels.filter((l) => typeof l === 'string');
    n.updatedAt = Date.now();
    save();
    return sendJson(res, 200, { note: n });
  }

  // DELETE /api/notes/:id (soft delete)
  if (method === 'DELETE' && parts.length === 3 && parts[1] === 'notes') {
    const n = db.notes.find((x) => x.id === parts[2]);
    if (!n) return sendJson(res, 404, { error: 'not found' });
    n.deleted = true;
    n.deletedAt = Date.now();
    save();
    return sendJson(res, 200, { ok: true });
  }

  // POST /api/notes/:id/restore
  if (method === 'POST' && parts.length === 4 && parts[1] === 'notes' && parts[3] === 'restore') {
    const n = db.notes.find((x) => x.id === parts[2]);
    if (!n) return sendJson(res, 404, { error: 'not found' });
    n.deleted = false;
    delete n.deletedAt;
    save();
    return sendJson(res, 200, { note: n });
  }

  // DELETE /api/trash
  if (method === 'DELETE' && parts.length === 2 && parts[1] === 'trash') {
    db.notes = db.notes.filter((n) => !n.deleted);
    save();
    return sendJson(res, 200, { ok: true });
  }

  // PATCH /api/labels/:id
  if (method === 'PATCH' && parts.length === 3 && parts[1] === 'labels') {
    const l = db.labels.find((x) => x.id === parts[2]);
    if (!l) return sendJson(res, 404, { error: 'not found' });
    let body;
    try { body = await readBody(req); } catch (e) { return sendJson(res, 400, { error: 'invalid body' }); }
    if (typeof body.name === 'string' && body.name.trim()) {
      const oldName = l.name;
      const newName = body.name.trim();
      l.name = newName;
      for (const n of db.notes) {
        if (n.labels && n.labels.includes(oldName)) {
          n.labels = n.labels.map((x) => (x === oldName ? newName : x));
        }
      }
      save();
    }
    return sendJson(res, 200, { label: l });
  }

  // DELETE /api/labels/:id
  if (method === 'DELETE' && parts.length === 3 && parts[1] === 'labels') {
    const idx = db.labels.findIndex((x) => x.id === parts[2]);
    if (idx === -1) return sendJson(res, 404, { error: 'not found' });
    const [removed] = db.labels.splice(idx, 1);
    for (const n of db.notes) {
      if (n.labels) n.labels = n.labels.filter((x) => x !== removed.name);
    }
    save();
    return sendJson(res, 200, { ok: true });
  }

  // POST /api/settings
  if (method === 'POST' && parts.length === 2 && parts[1] === 'settings') {
    let body;
    try { body = await readBody(req); } catch (e) { return sendJson(res, 400, { error: 'invalid body' }); }
    db.settings = Object.assign({}, db.settings, body);
    save();
    return sendJson(res, 200, { settings: db.settings });
  }

  return sendJson(res, 404, { error: 'not found' });
}

// ---------- Server ----------
const server = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://localhost');
  const pathname = u.pathname;
  if (pathname.startsWith('/api/')) {
    handleApi(req, res, pathname, u.searchParams).catch((e) => {
      sendJson(res, 500, { error: 'server error' });
    });
    return;
  }
  serveStatic(res, pathname);
});

load();
server.listen(PORT, () => {
  console.log('Keep backend listening on http://localhost:' + PORT);
});

